action.command:
cat > /tmp/dumpconventions.js <<'EOF'
const fs=require("fs");
function dumpStrings(p){
  const buf=fs.readFileSync(p);
  let out="";
  for(let i=0;i<buf.length;i++){const c=buf[i]; if(c>=32&&c<127) out+=String.fromCharCode(c); else out+="\n";}
  return out.split("\n").filter(s=>s.length>=4);
}
const files=[
 "io/swcode/urbo/build/logic/Common_conventions_gradle.class",
 "io/swcode/urbo/build/logic/Common_conventions_gradle$6.class",
 "io/swcode/urbo/build/logic/Common_conventions_gradle$6$1.class",
 "io/swcode/urbo/build/logic/Common_conventions_gradle$5.class",
];
for(const f of files){
  const p="/tmp/logic-extract/"+f;
  console.log("\n========== "+f.split("/").pop()+" ==========");
  try{
    const strs=dumpStrings(p);
    // print strings that look like repo/maven/url/dependency related
    const rel=strs.filter(s=>/maven|url|http|s3|amazonaws|releases|central|portal|google|jcenter|repo|swcode|buildlogic|token|github|gpr|credential|bearer/i.test(s));
    [...new Set(rel)].forEach(s=>console.log("   "+s));
  }catch(e){console.log("  (missing)");}
}
EOF
node /tmp/dumpconventions.js 2>&1

